package com.amalaei.engineering;
import org.json.*;
public class SoftwareWorkTest {
 static void check(boolean v){if(!v)throw new AssertionError();}
 public static void main(String[] args)throws Exception{JSONObject q=new JSONObject().put("type","subscription").put("title","اشتراك سنوي").put("status",1).put("followTime","09:00").put("details",new JSONObject().put("endDate","2026-10-12").put("renewDays","7").put("amount","1000").put("paid","300").put("paymentDate","2026-10-05"));SoftwareWork.validate(q);check(SoftwareWork.due(q,"renew").equals("2026-10-05"));check(SoftwareWork.due(q,"payment").equals("2026-10-05"));q.getJSONObject("details").put("paid","1000");check(SoftwareWork.due(q,"payment").isEmpty());for(int status:new int[]{4,5}){q.put("status",status);for(String kind:SoftwareWork.REMINDERS)check(SoftwareWork.due(q,kind).isEmpty());}q.put("status",1).put("type","development");q.getJSONObject("details").put("deliveryDate","2026-10-09");check(SoftwareWork.due(q,"renew").isEmpty());check(SoftwareWork.due(q,"delivery").equals("2026-10-09"));q.put("type","training");q.getJSONObject("details").put("sessionDate","2026-10-06").put("sessionTime","14:30");check(SoftwareWork.time(q,"session").equals("14:30"));q.getJSONObject("details").put("paid","1001");try{SoftwareWork.validate(q);throw new AssertionError();}catch(IllegalArgumentException expected){}System.out.println("PASS: renewal lead time, payment balance, closed request exclusions and independent session/delivery schedules.");}
}
